import React from 'react';
import { useForm } from 'react-hook-form';
import { Phone, Mail, MapPin, Clock, Facebook } from 'lucide-react';
import { Button } from '../components/Button';
import { COMPANY_INFO } from '../constants';

type FormData = {
  name: string;
  email: string;
  phone: string;
  service: string;
  message: string;
};

export const Contact: React.FC = () => {
  const { register, handleSubmit, formState: { errors, isSubmitting }, reset } = useForm<FormData>({
    mode: "onBlur"
  });

  const onSubmit = async (data: FormData) => {
    // Simulate API call with a delay
    await new Promise(resolve => setTimeout(resolve, 1000));
    console.log(data);
    alert(`Merci ${data.name}. Nous avons bien reçu votre demande. Nous vous contacterons sous peu.`);
    reset();
  };

  // Helper for input classes based on error state
  const getInputClass = (hasError: boolean) =>
    `w-full px-4 py-3 border rounded-md bg-zinc-800 text-white placeholder-gray-500 transition-all outline-none ${
      hasError 
        ? "border-brand-red focus:ring-2 focus:ring-brand-red" 
        : "border-zinc-700 focus:ring-2 focus:ring-brand-red focus:border-transparent"
    }`;

  return (
    <div className="bg-white">
       <div className="bg-brand-black py-16 text-center text-white">
        <h1 className="text-4xl font-extrabold uppercase">Contactez-nous</h1>
        <p className="mt-4 text-xl text-gray-400">Une question? Une urgence? Une soumission? Nous sommes là.</p>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">

          {/* Contact Info */}
          <div>
            <h2 className="text-2xl font-bold text-gray-900 mb-8 uppercase border-b-2 border-brand-red inline-block pb-2">Nos Coordonnées</h2>

            <div className="space-y-8">
              <div className="flex items-start gap-4">
                <div className="bg-gray-100 p-3 rounded-full">
                  <Phone className="text-brand-red w-6 h-6" />
                </div>
                <div>
                  <h3 className="font-bold text-lg">Téléphone</h3>
                  <p className="text-gray-600 mb-1">Disponible pour urgences</p>
                  <a href={`tel:${COMPANY_INFO.phoneClean}`} className="text-xl font-bold text-brand-black hover:text-brand-red">
                    {COMPANY_INFO.phone}
                  </a>
                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="bg-gray-100 p-3 rounded-full">
                  <Mail className="text-brand-red w-6 h-6" />
                </div>
                <div>
                  <h3 className="font-bold text-lg">Courriel</h3>
