                  <a href={`mailto:${COMPANY_INFO.email}`} className="text-lg text-brand-black hover:text-brand-red">
                    {COMPANY_INFO.email}
                  </a>
                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="bg-gray-100 p-3 rounded-full">
                  <MapPin className="text-brand-red w-6 h-6" />
                </div>
                <div>
                  <h3 className="font-bold text-lg">Localisation</h3>
                  <p className="text-gray-600">
                    {COMPANY_INFO.address}<br/>
                    {COMPANY_INFO.region}, Québec
                  </p>
                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="bg-gray-100 p-3 rounded-full">
                  <Clock className="text-brand-red w-6 h-6" />
                </div>
                <div>
                  <h3 className="font-bold text-lg">Heures d'ouverture</h3>
                  <p className="text-gray-600">Lundi - Vendredi : 7h00 - 18h00</p>
                  <p className="text-gray-600">Samedi - Dimanche : Urgences seulement</p>
                </div>
              </div>

              <div className="pt-8">
                <a 
                  href={COMPANY_INFO.facebookUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-2 bg-[#1877F2] text-white px-6 py-3 rounded hover:bg-blue-700 transition-colors font-bold"
                >
                  <Facebook size={20} />
                  Visitez notre page Facebook
                </a>
              </div>
            </div>
          </div>

          {/* Form */}
          <div className="bg-zinc-900 p-8 rounded-lg shadow-2xl border border-zinc-800">
            <h2 className="text-2xl font-bold text-white mb-6 uppercase">Demande de Soumission</h2>
