              <div>
                <label className="block text-sm font-medium text-gray-300 mb-1">Nom complet <span className="text-brand-red">*</span></label>
                <input 
                  type="text" 
                  {...register("name", { 
                    required: "Le nom complet est requis",
                    minLength: { value: 2, message: "Le nom doit contenir au moins 2 caractères" }
                  })}
                  className={getInputClass(!!errors.name)}
                  placeholder="Votre nom"
                  aria-invalid={!!errors.name}
                />
                {errors.name && <span role="alert" className="text-brand-red text-sm mt-1 block">{errors.name.message}</span>}
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-300 mb-1">Téléphone <span className="text-brand-red">*</span></label>
                  <input 
                    type="tel" 
                    {...register("phone", { 
                      required: "Le numéro de téléphone est requis",
                      pattern: {
                        value: /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/im,
                        message: "Format invalide (ex: 819-123-4567)"
