                  aria-invalid={!!errors.message}
                ></textarea>
                {errors.message && <span role="alert" className="text-brand-red text-sm mt-1 block">{errors.message.message}</span>}
              </div>

              <Button 
                type="submit" 
                fullWidth 
                disabled={isSubmitting}
                className={`text-lg py-4 font-extrabold tracking-wide uppercase shadow-lg hover:shadow-brand-red/20 ${isSubmitting ? 'opacity-70 cursor-not-allowed' : ''}`}
              >
                {isSubmitting ? 'Envoi en cours...' : 'Envoyer ma demande'}
              </Button>
              <p className="text-xs text-gray-500 text-center mt-2">Vos informations restent confidentielles.</p>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

